import 'package:flutter/material.dart';
import '../../core/network/api_client.dart';
class RegisterPage extends StatefulWidget { const RegisterPage({super.key}); @override State<RegisterPage> createState()=>_RegisterPageState(); }
class _RegisterPageState extends State<RegisterPage>{ final name=TextEditingController(); final email=TextEditingController(); final password=TextEditingController(); final api=ApiClient(); bool loading=false; String? error;
Future<void> register() async { setState(()=>{loading=true,error=null}); try { await api.post('/auth/register',{'name':name.text.trim(),'email':email.text.trim(),'password':password.text}); if(!mounted)return; ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Account created. Please sign in.'))); Navigator.pop(context); } catch(e){if(mounted)setState(()=>error=e.toString().replaceFirst('Exception: ',''));} finally{if(mounted)setState(()=>loading=false);} }
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Create learner account')),body:ListView(padding:const EdgeInsets.all(24),children:[Image.asset('assets/logo.png',height:100),const SizedBox(height:16),TextField(controller:name,decoration:const InputDecoration(labelText:'Full name',border:OutlineInputBorder())),const SizedBox(height:14),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',border:OutlineInputBorder())),const SizedBox(height:14),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password (8+ characters)',border:OutlineInputBorder())),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error))),const SizedBox(height:20),SizedBox(height:52,child:FilledButton(onPressed:loading?null:register,child:Text(loading?'Creating…':'Create account')))])); }
